-- 회복 정책(세계적 차원): 신규 5개 INSERT + 기존 decriminalization 본문 보강
-- 정의/본문/심화 전부 신규 작성. 현행 사실은 웹 검색으로 확인(2024~2025).
-- 실행: psql -h localhost -U postgres -d addiction_news -f inject_recovery_policy.sql
BEGIN;
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('portugal-model', '포르투갈 모델', 'Portuguese Model', 'policy', '2001년 포르투갈이 모든 마약의 개인적 사용·소지를 형사처벌 대상에서 제외하고, 처벌 대신 치료·보건·사회재통합으로 연결한 정책 모델이다. 심각한 헤로인 위기에 대한 공중보건적 대응으로 시작되었으며, 이후 세계 각국이 참고하는 대표적 ''처벌에서 치료로'' 전환 사례가 되었다.', '약물을 소지하다 적발된 사람을 감옥이 아니라 의사·사회복지사·법률가로 구성된 위원회로 보내 치료·상담으로 연결하는 방식.', '[]'::jsonb, true, false, '[{"h": "무엇인가", "p": "포르투갈 모델은 마약 사용·소지를 ''합법화''한 것이 아니라 ''비범죄화''한 것이다. 마약은 여전히 불법이지만, 개인적 사용을 위한 소량 소지는 형사처벌 대신 행정적 절차로 다룬다. 적발된 사람은 처벌 위원회가 아니라 보건·사회 전문가로 구성된 위원회를 만나 치료와 지원으로 연결된다."}, {"h": "왜 시작됐나", "p": "1990년대 포르투갈은 인구의 상당수가 헤로인에 의존하고, 약물 관련 사망과 HIV 감염이 유럽 최고 수준에 이르는 심각한 위기를 겪었다. 체포·수감·낙인 중심의 전통적 처벌 접근이 위기를 오히려 심화시키자, 2001년 문제를 범죄가 아니라 공중보건 사안으로 재정의하는 근본적 전환을 택했다."}, {"h": "어떤 결과가 있었나", "p": "전환 이후 자발적으로 치료에 들어오는 사람이 크게 늘고, 약물 관련 사망·HIV 감염·수감이 뚜렷이 감소한 것으로 보고된다. 약물 사용 자체가 폭증하지 않았고, 사회적 비용도 절감됐다는 평가가 많다. 다만 이 성과가 비범죄화 ''단독''의 효과인지, 함께 확충한 치료·사회 인프라의 효과인지를 두고 해석이 갈린다."}, {"h": "무엇을 시사하나", "p": "핵심 교훈은 비범죄화가 그 자체로 만능이 아니라, 치료·재통합 인프라와 함께 갈 때 작동한다는 점이다. 처벌을 없애는 것만으로는 부족하고, 그 자리를 채우는 보건·사회 시스템이 있어야 한다. 이 점이 다른 나라들이 포르투갈을 모방할 때 가장 자주 놓치는 부분이다."}]'::jsonb, '[{"h": "성과 해석의 논쟁", "p": "포르투갈 모델의 성과는 널리 인용되지만, 인과관계의 엄밀성에 대한 비판도 있다. 일부 지표 개선이 비범죄화 이전부터 시작됐다는 지적, 통계적 유의성에 대한 이견, 그리고 동시에 진행된 치료 확충·경제 변화 등 교란 요인을 충분히 통제하지 못했다는 반론이 제기된다. 근래에는 재정 삭감과 치료 인프라 약화로 문제가 일부 재발했다는 보도도 나온다."}, {"h": "비범죄화와 인프라의 결합", "p": "포르투갈 사례의 핵심은 ''비범죄화 + 보건·사회 투자''라는 결합에 있다. 처벌 폐지(감형)와 치료·주거·고용 지원의 확충이 동시에 이뤄졌기에 성과가 났다는 것이 다수 견해다. 이 결합을 분리해 비범죄화만 도입하면 결과가 달라질 수 있음을, 뒤의 오리건 사례가 보여준다."}, {"h": "국제적 준거로서의 위상", "p": "포르투갈 모델은 UNODC·WHO·인권기구가 지지하는 ''공중보건·인권 기반 접근''의 상징적 준거가 되었다. 동시에 처벌 중심 국가들이 ''마약 청정 사회''를 명분으로 이를 비판하는 대립 구도의 한 축이기도 하다. 회복 정책을 둘러싼 세계적 가치 충돌이 이 모델을 통해 드러난다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('oregon-measure110', '오리건 실험과 재범죄화', 'Oregon''s Measure 110 and Recriminalization', 'policy', '미국 오리건주가 2020년 주민투표(Measure 110)로 소량 마약 소지를 비범죄화했다가, 2024년 이를 되돌려 재범죄화한 사례다. 포르투갈식 접근을 미국에서 처음 시도했으나 기대한 성과를 내지 못하고 후퇴한 대표적 실패·후퇴 사례로 자주 인용된다.', '소량 마약 소지를 벌금 수준으로 완화했다가, 공공장소 약물 사용과 과용 증가 논란 속에 4년 만에 다시 경범죄로 되돌린 것.', '[]'::jsonb, true, false, '[{"h": "무엇인가", "p": "오리건은 2020년 주민투표로 헤로인·코카인 등 소량 소지를 비범죄화하고, 마약세 수입을 치료에 투입하기로 했다. 미국의 한 주가 강경 마약 정책에서 벗어나 보건 중심으로 전환한 첫 시도였다. 그러나 2024년 주의회가 이를 되돌려, 소량 소지를 다시 경범죄로 규정하는 재범죄화법을 통과시켰고 그해 발효됐다."}, {"h": "왜 후퇴했나", "p": "비범죄화 이후 공공장소 약물 사용과 과용 문제가 두드러지면서 정책에 대한 지지가 약해졌다. 핵심 문제로 지목된 것은 ''처벌은 없앴으나 치료로 연결하는 인프라가 제때 작동하지 않았다''는 점이다. 처벌을 대신할 보건·사회 시스템이 준비되지 않은 채 비범죄화만 앞서 나갔다는 평가가 많다."}, {"h": "포르투갈과 무엇이 달랐나", "p": "두 곳 모두 소량 소지를 비범죄화했지만 결과가 갈렸다. 포르투갈은 치료·재통합 인프라를 함께 갖췄고 오랜 시간에 걸쳐 정착시킨 반면, 오리건은 그 연결 고리가 약했고 과용 위기(펜타닐)라는 다른 환경에 놓여 있었다. 같은 정책도 인프라와 맥락에 따라 전혀 다른 결과를 낸다는 것을 보여준다."}, {"h": "무엇을 남겼나", "p": "오리건 사례는 비범죄화 논쟁에 신중함을 더했다. ''처벌을 없애는 것''과 ''치료로 연결하는 것''은 별개이며, 후자가 없으면 전자만으로는 실패할 수 있다는 교훈이다. 재범죄화 이후에도 각 지역이 형사처벌 대신 치료로 우회시키는 프로그램을 병행하도록 한 점은, 완전한 처벌 회귀는 아님을 시사한다."}]'::jsonb, '[{"h": "실패인가 미완성인가", "p": "오리건 실험을 ''비범죄화의 실패''로 단정할지, ''인프라 없는 성급한 도입의 실패''로 볼지에 대한 해석이 갈린다. 비판자는 비범죄화 자체가 무질서를 낳았다고 보고, 옹호자는 치료 예산 집행 지연과 펜타닐 위기라는 교란 요인을 지목한다. 이 해석 차이가 이후 미국 내 정책 논쟁의 핵심이 되었다."}, {"h": "펜타닐 환경이라는 변수", "p": "오리건의 실험은 합성 아편류(펜타닐) 과용이 급증하던 시기와 겹쳤다. 같은 정책이라도 치명적 물질이 시장을 지배하는 환경에서는 위험이 증폭될 수 있다. 이는 회복 정책이 물질 환경의 변화와 분리해 평가될 수 없음을 보여주는 사례다."}, {"h": "정책 되돌림의 정치학", "p": "한 번 도입한 개혁적 정책이 단기 성과 부재와 여론 악화로 빠르게 뒤집히는 과정은, 근거보다 체감 무질서와 정치적 압력이 정책을 좌우할 수 있음을 드러낸다. 장기적 효과를 기다리기 어려운 정치 환경이 회복 지향 개혁의 지속을 어렵게 하는 구조적 요인으로 지적된다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('rosc', '회복지향 시스템(ROSC)', 'Recovery-Oriented Systems of Care', 'policy', '중독을 일회성 치료 사건이 아니라 오래 이어지는 회복 여정으로 보고, 예방부터 치료·지속관리·장기 회복까지를 지역사회가 연결된 망으로 지원하는 정책 틀이다. ''치료하고 내보내기''에서 ''치료하고 연결하고 지속시키기''로 초점을 옮기며, 당사자 중심·강점 기반을 핵심 원리로 삼는다.', '치료를 마친 사람에게 주거·고용·또래 지지·의료를 하나의 연결된 망으로 제공해, 회복이 일상에서 유지되도록 돕는 지역 단위 체계.', '[]'::jsonb, true, false, '[{"h": "무엇인가", "p": "회복지향 시스템(ROSC)은 중독 대응을 ''급성 치료 에피소드''가 아니라 ''전 생애에 걸친 회복 여정''을 중심으로 재편하는 접근이다. 예방, 조기개입, 치료, 지속관리, 장기 회복을 하나의 연속선으로 보고, 임상 서비스와 비임상 지원(주거·고용·또래 지지)을 지역사회 망으로 연결한다."}, {"h": "무엇이 다른가", "p": "전통적 치료가 ''치료 완료율·재원 기간·단기 단약'' 같은 지표에 초점을 둔다면, ROSC는 여기에 회복자본의 축적, 지역사회 통합, 고용·주거 안정, 지속되는 웰빙 같은 장기 성과를 더한다. 성공의 정의 자체가 ''증상 제거''에서 ''삶의 재건''으로 넓어진다."}, {"h": "왜 중요한가", "p": "치료만으로는 부족하다는 인식이 배경이다. 안정된 주거와 관계, 일자리가 없는 환경으로 돌아가면 치료 효과가 유지되기 어렵다. ROSC는 회복을 개인의 의지가 아니라 그를 둘러싼 자원과 관계의 문제로 재정의하고, 그 자원을 사회가 함께 떠받치도록 설계한다."}, {"h": "어떻게 구현되나", "p": "또래 회복 코치, 회복 주거, 고용·교육 연계, 가족 지원, 지역 회복 공동체가 임상 치료와 나란히 배치된다. 여러 나라·주 정부가 이 틀을 채택하고 있으며, 캐나다 앨버타주는 2024년 전담 기관과 연구센터를 세워 ROSC를 제도화한 대표 사례다."}]'::jsonb, '[{"h": "회복자본과의 결합", "p": "ROSC의 이론적 심장은 ''회복자본''이다. 회복은 단약 그 자체를 넘어 건강·관계·의미 같은 자원의 축적이며, 초기 단약이 자원을 낳고 그 자원이 다시 단약을 지속시키는 상호 강화 관계로 이해된다. ROSC는 이 회복자본을 키우는 지원 서비스를 치료와 함께 배치하는 것을 원리로 삼는다."}, {"h": "성과 측정의 전환", "p": "ROSC는 성과 지표를 근본적으로 바꾼다. 단기 단약률 대신 장기 회복 궤적, 회복자본 발달, 지역사회 통합, 고용·주거 안정, 지속적 웰빙을 측정한다. 이 전환은 기관에 종단적 성과 측정 체계를 요구하며, 재정 지원 기준도 이에 맞춰 재편되는 흐름을 낳고 있다."}, {"h": "신앙·지역 공동체와의 접점", "p": "ROSC는 지역의 다양한 자원—의료·사회서비스뿐 아니라 신앙 공동체와 회복 공동체—을 회복의 파트너로 포함한다. 이 점에서 신앙 기반 회복 공동체나 생태 기반 회복 마을 같은 모델과 자연스럽게 접점을 갖는다. 회복을 개인이 아니라 공동체의 과제로 보는 관점이 그 바탕에 있다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('international-drug-policy', '국제기구의 회복 정책', 'International Drug Policy (UNODC·WHO)', 'policy', 'UNODC(유엔마약범죄사무소)와 WHO(세계보건기구)를 중심으로 한 국제 사회의 마약·중독 정책 방향으로, 공급·수요를 함께 다루되 공중보건과 인권에 기반한 균형 접근을 지향한다. 중독을 예방·치료 가능한 다인성 건강 장애로 규정하고, 회복 관리와 사회재통합을 강조하는 흐름이 강화되고 있다.', 'UNODC와 WHO가 공동 프로그램을 통해 각국의 치료 시스템 질을 평가하고, 처벌 대신 치료로 우회시키는 대안 조치를 권장하는 활동.', '[]'::jsonb, true, false, '[{"h": "무엇인가", "p": "국제 마약 정책은 세 개의 국제 마약 통제 협약을 토대로 하되, 그 목적을 ''인류의 건강과 복지''에 두고 공급 억제와 수요 감소를 함께 추구한다. UNODC와 WHO는 중독을 범죄가 아니라 예방·치료 가능한 다인성 건강 장애로 규정하고, 근거 기반·인권 기반 접근을 각국에 권고한다."}, {"h": "어떤 방향인가", "p": "근래 국제 사회는 처벌 일변도에서 예방·치료·회복 관리로 무게중심을 옮기고 있다. UNODC·WHO 공동 프로그램은 치료 시스템의 질을 평가·개선하고, 형사처벌 대신 치료로 연결하는 대안 조치를 확산하며, 재활과 회복 관리를 강조한다. 피해감소를 인권·보건 관점에서 인정하는 결의도 채택됐다."}, {"h": "낙인 감소의 강조", "p": "국제기구들은 낙인을 회복의 핵심 장벽으로 지목하며 ''사람 중심'' 접근을 강조한다. 중독을 도덕적 결함이 아니라 치료 가능한 질환으로 보는 언어와 정책이 국제 규범 차원에서 권고된다. 이는 각국의 낙인 완화 정책과 회복 지향 개혁의 국제적 근거가 된다."}, {"h": "무엇을 시사하나", "p": "국제 규범은 개별 국가가 회복 정책을 설계할 때 참고하는 공통의 틀을 제공한다. 다만 국제 권고와 각국의 실제 정책 사이에는 큰 간극이 있으며, 이 틀을 어떻게 국내 맥락에 적용하느냐가 관건이다. 한국을 포함한 각국의 정책도 이 국제적 흐름과의 관계 속에서 이해할 수 있다."}]'::jsonb, '[{"h": "인권 대 통제의 긴장", "p": "국제 마약 정책 안에는 ''공중보건·인권''을 강조하는 흐름과 ''엄격한 통제·마약 청정 사회''를 강조하는 흐름이 공존한다. 일부 국가는 ''공동체의 마약 없는 삶''을 명분으로 처벌 정책을 정당화하고, 인권기구·시민사회는 이를 사용자에 대한 낙인·범죄화로 비판한다. 국제기구의 문서 안에서도 이 긴장이 드러난다."}, {"h": "강제 치료 논쟁", "p": "국제 사회는 ''강제 치료''가 인권을 침해할 수 있음을 인정하면서도, 여전히 여러 나라에서 시행된다. 자발성에 기반한 근거 기반 치료가 원칙으로 권고되지만, 형사사법과 치료의 경계, 동의 없는 개입의 정당성은 계속되는 논쟁 지점이다."}, {"h": "규범과 현실의 간극", "p": "국제 권고는 공중보건·인권 기반 접근을 지향하지만, 실제 각국 정책은 처벌 중심부터 보건 중심까지 스펙트럼이 넓다. 자원·정치·문화의 차이로 인해 국제 규범이 각국에서 균일하게 구현되지 않으며, 이 간극을 좁히는 것이 국제 협력의 과제로 남아 있다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
INSERT INTO encyclopedia_terms (id, term_ko, term_en, category, definition, example, see_also, trend, sensitive, body, advanced, published, updated_at) VALUES ('recovery-policy-global', '회복 정책의 세계적 비교', 'Global Comparison of Recovery Policy', 'policy', '중독에 대한 사회의 대응을 처벌 중심부터 공중보건·회복 중심까지의 스펙트럼으로 놓고, 나라별 접근을 비교하는 관점이다. 같은 문제라도 어떤 철학과 인프라를 택하느냐에 따라 결과가 크게 달라지며, 최근 세계적 흐름은 처벌에서 예방·치료·회복 지원으로 이동하고 있다.', '같은 소량 소지 문제를 두고, 한 나라는 수감으로, 다른 나라는 치료 연계로 대응해 전혀 다른 사회적 결과를 낳는 것.', '[]'::jsonb, true, false, '[{"h": "무엇을 비교하나", "p": "회복 정책은 하나가 아니라 스펙트럼이다. 한쪽 끝에는 공급 차단과 형사처벌을 앞세우는 강경 접근(마약과의 전쟁)이, 다른 쪽 끝에는 피해감소와 회복 지원을 앞세우는 보건 접근이 있다. 대부분의 나라는 그 사이 어딘가에 위치하며, 시기와 정치에 따라 이동한다."}, {"h": "흐름은 어디로", "p": "근래의 국제적 흐름은 처벌 일변도의 한계가 드러나면서 예방·치료·회복 지원 쪽으로 무게중심을 옮기고 있다. 국제기구는 공중보건·인권 기반 접근을 권고하고, 여러 나라가 처벌 대신 치료로 우회시키는 제도를 도입한다. 다만 이 이동은 직선이 아니라, 오리건처럼 후퇴가 섞인 굴곡의 과정이다."}, {"h": "무엇이 결과를 가르나", "p": "핵심 교훈은 정책의 이름(비범죄화·합법화·처벌)보다 그것을 뒷받침하는 인프라와 지속성이 결과를 좌우한다는 것이다. 같은 비범죄화도 치료·재통합 시스템과 함께 가면 성과를 내지만(포르투갈), 인프라 없이 도입하면 후퇴한다(오리건). 정책은 진공이 아니라 물질 환경·자원·문화 속에서 작동한다."}, {"h": "한국에 주는 함의", "p": "세계적 비교는 한국의 정책을 성찰하는 거울이 된다. 어떤 접근을 택하든, 처벌을 대신하거나 보완할 치료·회복 인프라의 두께가 관건이며, 회복을 개인의 의지가 아니라 사회가 함께 떠받치는 과제로 볼 때 지속 가능한 결과가 나온다는 점을 각국 사례가 공통으로 보여준다."}]'::jsonb, '[{"h": "비범죄화·합법화·피해감소의 구분", "p": "세계 정책을 비교할 때 개념 구분이 중요하다. 비범죄화는 형사처벌을 없애되 불법성은 유지하는 것, 합법화는 합법적 시장을 허용하는 것, 피해감소는 사용 중단을 전제하지 않고 해악을 줄이는 접근이다. 이 셋을 혼동하면 각국 사례의 성과·한계를 잘못 읽게 된다."}, {"h": "근거 대 가치의 충돌", "p": "회복 정책은 근거만으로 결정되지 않는다. ''마약 청정 사회''라는 도덕적 가치와 ''해악 최소화''라는 실용적 가치가 충돌하며, 같은 데이터도 상반된 결론으로 해석된다. 정책 비교는 효과성뿐 아니라 그 사회가 어떤 가치를 우선하는지를 함께 드러낸다."}, {"h": "행동중독으로의 확장 가능성", "p": "기존 회복 정책 논의는 주로 물질(마약)에 집중돼 왔으나, 도박·게임 등 행동중독으로의 확장이 과제로 남아 있다. 사행산업 규제, 게임 이용자 보호, 디지털 환경 설계 같은 영역은 물질 정책과 다른 접근을 요구하며, 이 부분의 국제 비교는 아직 초기 단계다."}]'::jsonb, true, now()) ON CONFLICT (id) DO UPDATE SET term_ko=EXCLUDED.term_ko, term_en=EXCLUDED.term_en, category=EXCLUDED.category, definition=EXCLUDED.definition, example=EXCLUDED.example, see_also=EXCLUDED.see_also, trend=EXCLUDED.trend, body=EXCLUDED.body, advanced=EXCLUDED.advanced, updated_at=now();
UPDATE encyclopedia_terms SET body='[{"h": "무엇인가", "p": "비범죄화는 마약의 개인적 사용·소량 소지를 형사처벌 대상에서 제외하되, 합법화와는 구분되는 정책이다. 마약은 여전히 불법이지만, 사용자를 감옥이 아니라 치료·보건으로 연결하는 데 초점을 둔다. 처벌을 완전히 없애는 것이 아니라 형사처벌을 행정적·보건적 대응으로 바꾸는 것이다."}, {"h": "합법화와 무엇이 다른가", "p": "흔히 혼동되지만 비범죄화와 합법화는 다르다. 합법화는 합법적 생산·판매 시장을 허용하는 것이고, 비범죄화는 불법성을 유지한 채 사용자에 대한 형사처벌만 완화하는 것이다. 이 구분을 놓치면 각국 사례의 성과와 한계를 잘못 해석하게 된다."}, {"h": "성과와 후퇴", "p": "포르투갈은 비범죄화를 치료·재통합 인프라와 함께 도입해 사망·감염·수감을 줄인 대표 성공 사례로 꼽힌다. 반면 미국 오리건은 2020년 비범죄화를 도입했다가 인프라 미비와 과용 위기 속에 2024년 재범죄화로 되돌렸다. 같은 정책도 인프라와 맥락에 따라 결과가 갈린다."}, {"h": "핵심은 인프라", "p": "두 사례가 공통으로 남긴 교훈은, 비범죄화가 그 자체로 해법이 아니라 처벌을 대신할 치료·사회 시스템이 있을 때 작동한다는 것이다. 처벌을 없애는 결정보다, 그 자리를 무엇으로 채우느냐가 결과를 좌우한다."}]'::jsonb, advanced='[{"h": "포르투갈과 오리건의 대조", "p": "두 사례의 대조는 비범죄화 연구의 핵심 텍스트다. 포르투갈은 오랜 준비와 치료 인프라, 사회재통합 지원을 결합해 정착시킨 반면, 오리건은 치료 연계가 약하고 펜타닐 위기라는 환경에 놓여 단기간에 후퇴했다. 정책의 성패가 정책 자체보다 실행 조건에 크게 좌우됨을 보여준다."}, {"h": "근거 해석의 논쟁", "p": "비범죄화의 효과는 방법론적으로 논쟁적이다. 관찰된 개선이 비범죄화 단독의 효과인지, 동시에 진행된 치료 확충·사회 변화의 효과인지 분리하기 어렵다. 지지자와 비판자가 같은 데이터에서 상반된 결론을 끌어내는 경우가 많아, 신중한 해석이 요구된다."}, {"h": "국제 규범과의 관계", "p": "비범죄화는 UNODC·WHO·인권기구가 지지하는 공중보건·인권 기반 접근과 맞닿아 있으나, 처벌 중심 국가들과의 가치 충돌 지점이기도 하다. 회복 정책을 둘러싼 국제적 긴장이 비범죄화 논쟁에 집약되어 나타난다."}]'::jsonb, updated_at=now() WHERE id='decriminalization';
COMMIT;
-- 확인:
SELECT id, category, jsonb_array_length(body) b, jsonb_array_length(advanced) a FROM encyclopedia_terms WHERE id IN ('portugal-model','oregon-measure110','rosc','international-drug-policy','recovery-policy-global','decriminalization') ORDER BY id;
